#!/data/data/com.termux/files/usr/bin/bash
set -Eeuo pipefail
cd "$HOME/companyos"
source "$HOME/.companyos_launch_env" 2>/dev/null || true

STAMP="$(date +%Y%m%d_%H%M%S)"
BK="$HOME/companyos/.companyos_backups/evidence_acquisition_v19_$STAMP"
mkdir -p "$BK"
cp -a companyos/runtime/profit_first_dispatcher.py "$BK/" 2>/dev/null || true
cp -a companyos/runtime/service_supervisor.py "$BK/" 2>/dev/null || true

echo "" | base64 -d > companyos/runtime/autonomous_evidence_acquisition.py

echo "" | base64 -d > "$PREFIX/tmp/companyos_evidence_dispatch_patch.py"
python "$PREFIX/tmp/companyos_evidence_dispatch_patch.py"
rm -f "$PREFIX/tmp/companyos_evidence_dispatch_patch.py"

echo "" | base64 -d > "$PREFIX/tmp/companyos_evidence_supervisor_patch.py"
python "$PREFIX/tmp/companyos_evidence_supervisor_patch.py"
rm -f "$PREFIX/tmp/companyos_evidence_supervisor_patch.py"

echo "" | base64 -d > scripts/companyos_evidencectl
chmod +x scripts/companyos_evidencectl
echo "" | base64 -d > tests/test_autonomous_evidence_acquisition_v19.py

echo "[1/9] Compile"
python -m py_compile companyos/runtime/autonomous_evidence_acquisition.py companyos/runtime/profit_first_dispatcher.py companyos/runtime/service_supervisor.py tests/test_autonomous_evidence_acquisition_v19.py

echo "[2/9] Evidence tests"
python -m unittest tests.test_autonomous_evidence_acquisition_v19 -v

echo "[3/9] Generate evidence tasks"
scripts/companyos_evidencectl once | tee .companyos_runtime/evidence_acquisition_v19_first_cycle.json || true

echo "[4/9] Show evidence queue"
scripts/companyos_evidencectl queue || true

echo "[5/9] Verify dispatcher receives research tasks"
python - <<'PY'
from companyos.runtime.profit_first_dispatcher import build_goal
g=build_goal()
print("EVIDENCE_TASKS_IN_DISPATCHER=", "AUTONOMOUS EVIDENCE ACQUISITION TASKS" in g)
print("GOAL_LENGTH=",len(g))
PY

echo "[6/9] Run one guarded dispatcher cycle"
python - <<'PY'
from companyos.runtime.profit_first_dispatcher import maybe_dispatch
print(maybe_dispatch(min_idle_cycles=0,cooldown_seconds=0))
PY

echo "[7/9] Re-scan canonical research outputs"
sleep 3
scripts/companyos_evidencectl once || true

echo "[8/9] Commit/push"
git add companyos/runtime/autonomous_evidence_acquisition.py companyos/runtime/profit_first_dispatcher.py companyos/runtime/service_supervisor.py scripts/companyos_evidencectl tests/test_autonomous_evidence_acquisition_v19.py
git diff --cached --quiet || git commit -m "Add autonomous evidence acquisition and validation bridge"
BRANCH="$(git branch --show-current)"
[ -n "$BRANCH" ] && git push origin "$BRANCH" || true

echo "[9/9] Restart + verify"
scripts/companyosctl restart || true
sleep 8

echo "===== EVIDENCE ACQUISITION ====="
scripts/companyos_evidencectl status || true
echo "===== EVIDENCE QUEUE ====="
scripts/companyos_evidencectl queue || true
echo "===== ACTION BRIDGE ====="
scripts/companyos_actionbridgectl status || true
echo "===== OUTCOME LEARNING ====="
scripts/companyos_outcomectl status || true
echo "===== SERVICES ====="
scripts/companyosctl status || true

echo "BACKUP=$BK"
echo "COMPANYOS_AUTONOMOUS_EVIDENCE_ACQUISITION_V19=PASS"
